from __future__ import annotations

import inspect
from dataclasses import dataclass
from typing import Callable, Sequence

from mcp.server.fastmcp import FastMCP
from mcp.types import CallToolResult

from robot_interface import GalbotInterface
from robot_interface import iter_mcp_tool_bindings

from .result_models import to_call_tool_result
from .runtime import GalbotRuntime


class ToolRegistryError(RuntimeError):
    """Raised when the discovered tool surface is inconsistent."""


@dataclass(frozen=True)
class ToolSpec:
    method_name: str
    name: str
    description: str
    dangerous: bool
    result_mode: str
    signature: inspect.Signature


def _tool_signature(method) -> inspect.Signature:
    signature = inspect.signature(method)
    resolved_annotations = inspect.get_annotations(method, eval_str=True)
    parameters = [
        parameter.replace(
            annotation=resolved_annotations.get(parameter.name, inspect.Signature.empty)
        )
        for parameter in list(signature.parameters.values())[1:]
    ]
    return_annotation = resolved_annotations.get("return", inspect.Signature.empty)
    return signature.replace(parameters=parameters, return_annotation=return_annotation)


def discover_tool_specs(interface_cls: type[GalbotInterface] = GalbotInterface) -> tuple[ToolSpec, ...]:
    specs: list[ToolSpec] = []
    for binding in iter_mcp_tool_bindings(interface_cls):
        specs.append(
            ToolSpec(
                method_name=binding.method_name,
                name=binding.metadata.name,
                description=binding.metadata.description,
                dangerous=binding.metadata.dangerous,
                result_mode=binding.metadata.result_mode,
                signature=_tool_signature(binding.function),
            )
        )
    validate_tool_specs(specs)
    return tuple(specs)


def validate_tool_specs(specs: Sequence[ToolSpec]) -> None:
    names = [spec.name for spec in specs]
    duplicate_names = sorted({name for name in names if names.count(name) > 1})
    if duplicate_names:
        raise ToolRegistryError("Duplicate MCP tool names: " + ", ".join(duplicate_names))

    method_names = [spec.method_name for spec in specs]
    duplicate_methods = sorted(
        {method_name for method_name in method_names if method_names.count(method_name) > 1}
    )
    if duplicate_methods:
        raise ToolRegistryError(
            "Duplicate MCP method registrations: " + ", ".join(duplicate_methods)
        )


def _make_tool(runtime: GalbotRuntime, spec: ToolSpec) -> Callable[..., CallToolResult]:
    def tool(*args, **kwargs) -> CallToolResult:
        bound = spec.signature.bind(*args, **kwargs)
        return to_call_tool_result(runtime.call_tool(spec, **bound.arguments))

    annotations = {
        parameter.name: parameter.annotation
        for parameter in spec.signature.parameters.values()
        if parameter.annotation is not inspect.Signature.empty
    }
    annotations["return"] = CallToolResult

    tool.__name__ = spec.name
    tool.__qualname__ = spec.name
    tool.__doc__ = spec.description
    tool.__signature__ = spec.signature
    tool.__annotations__ = annotations
    return tool


def register_tool_specs(
    mcp: FastMCP,
    runtime: GalbotRuntime,
    specs: Sequence[ToolSpec],
) -> None:
    validate_tool_specs(specs)
    for spec in specs:
        mcp.add_tool(
            _make_tool(runtime, spec),
            name=spec.name,
            description=spec.description,
            structured_output=False,
        )


INTERFACE_TOOL_SPECS = discover_tool_specs()

