def pose_dict(pose: Iterable[float]) -> dict[str, float]:
    values = list(pose)
    if len(values) != 7:
        raise ValueError(f"Expected a 7-element pose, got {len(values)}")
    return {
        "x": float(values[0]),
        "y": float(values[1]),
        "z": float(values[2]),
        "qx": float(values[3]),
        "qy": float(values[4]),
        "qz": float(values[5]),
        "qw": float(values[6]),
    }


def json_safe(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [json_safe(item) for item in value]
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    return value


def encode_png(image: np.ndarray) -> bytes:
    image_array = np.asarray(image)
    if image_array.dtype != np.uint8:
        image_array = np.clip(image_array, 0, 255).astype(np.uint8)
    success, encoded = cv2.imencode(".png", np.ascontiguousarray(image_array))
    if not success:
        raise RuntimeError("Failed to encode image as PNG")
    return encoded.tobytes()


def depth_summary(depth: np.ndarray) -> dict[str, Any]:
    depth_array = np.asarray(depth)
    finite = depth_array[np.isfinite(depth_array)]
    return {
        "shape": list(depth_array.shape),
        "dtype": str(depth_array.dtype),
        "min": float(finite.min()) if finite.size else None,
        "max": float(finite.max()) if finite.size else None,
    }


def depth_preview_png(depth: np.ndarray) -> bytes:
    depth_array = np.asarray(depth, dtype=np.float32)
    finite_mask = np.isfinite(depth_array)
    preview = np.zeros(depth_array.shape, dtype=np.uint8)

    if finite_mask.any():
        finite_values = depth_array[finite_mask]
        min_value = float(finite_values.min())
        max_value = float(finite_values.max())
        if max_value > min_value:
            scaled = (depth_array[finite_mask] - min_value) / (max_value - min_value)
            preview[finite_mask] = np.clip(scaled * 255.0, 0.0, 255.0).astype(np.uint8)

    colored = cv2.applyColorMap(preview, cv2.COLORMAP_TURBO)
    return encode_png(colored)


class GalbotRuntime:
    """Process-local runtime that owns the ``GalbotInterface`` lifecycle."""

    def __init__(
        self,
        config: ServiceConfig,
        interface_factory: Callable[..., Any] | None = None,
        config_loader: Callable[[Path], Any] | None = None,
    ):
        self._config = config
        self._lock = threading.RLock()
        self._interface_factory = interface_factory or GalbotInterface
        self._config_loader = config_loader or OmegaConf.load
        self._interface: Any | None = None
        self._interface_cfg: Any | None = None
        self._started = False

    @property
    def interface(self) -> Any | None:
        return self._interface

    @property
    def interface_cfg(self) -> Any | None:
        return self._interface_cfg

    def start(self) -> None:
        with self._lock:
            if self._started:
                return

            if self._config.sdk_root is not None:
                os.environ["GALBOTSDK_ROOT"] = str(self._config.sdk_root)

            self._interface_cfg = self._config_loader(self._config.interface_config_path)
            self._interface = self._interface_factory(
                self._interface_cfg,
                robot_cfg=self._config.robot_cfg,
                auto_reset=False,
            )
            self._started = True

    def close(self) -> None:
        with self._lock:
            self._interface = None
            self._interface_cfg = None
            self._started = False

    def _require_started(self) -> Any:
        if not self._started or self._interface is None:
            raise RuntimeError("Galbot runtime is not started")
        return self._interface

    def call_tool(self, binding: Any, **arguments: Any) -> ToolResponse:
        with self._lock:
            interface = self._require_started()
            method = getattr(interface, binding.method_name)

            try:
                result = method(**arguments)
            except Exception as exc:
                return ToolResponse(
                    payload={
                        "error": str(exc),
                        "error_type": type(exc).__name__,
                        "arguments": json_safe(arguments),
                    },
                    is_error=True,
                )

            result_mode = getattr(binding, "result_mode", None)
            if result_mode is None:
                result_mode = binding.metadata.result_mode
            if result_mode == "action":
                success = bool(result)
                return ToolResponse(
                    payload={
                        "success": success,
                        "arguments": json_safe(arguments),
                    },
                    is_error=not success,
                )
            if result_mode == "reachability":
                return ToolResponse(
                    payload={
                        "reachable": bool(result),
                        "arguments": json_safe(arguments),
                    },
                    is_error=False,
                )
            if result_mode == "pose":
                raw_pose = json_safe(list(result))
                return ToolResponse(
                    payload={
                        "raw_pose": raw_pose,
                        "pose": pose_dict(raw_pose),
                    }
                )
            if result_mode == "status":
                return ToolResponse(payload=json_safe(dict(result)))
            if result_mode == "reset":
                return self._observation_response(result, reset_executed=True)
            if result_mode == "observation":
                return self._observation_response(result)
            if result_mode == "image_sequence":
                return self._image_sequence_response(result)

            raise RuntimeError(f"Unsupported MCP result mode: {result_mode}")

    def _image_sequence_response(self, result: dict[str, Any]) -> ToolResponse:
        result_payload = dict(result)
        photos = result_payload.get("photos")
        if not isinstance(photos, list):
            raise ValueError("Expected image_sequence result with photos list")

        payload = {
            key: json_safe(value)
            for key, value in result_payload.items()
            if key != "photos"
        }
        payload_photos: list[dict[str, Any]] = []
        images: list[ImageArtifact] = []
        for index, photo in enumerate(photos, start=1):
            if not isinstance(photo, dict):
                raise ValueError("Expected every image_sequence photo to be a dict")
            if "image" not in photo:
                raise ValueError("Expected every image_sequence photo to include image")

            image_array = np.asarray(photo["image"])
            photo_payload = {
                key: value
                for key, value in photo.items()
                if key != "image"
            }
            photo_payload["image_summary"] = {
                "shape": list(image_array.shape),
                "dtype": str(image_array.dtype),
            }
            payload_photos.append(json_safe(photo_payload))
            images.append(
                ImageArtifact(
                    camera=str(photo_payload.get("camera", f"photo_{index}")),
                    data=encode_png(image_array),
                    mime_type="image/png",
                )
            )

        payload["photos"] = payload_photos
        return ToolResponse(payload=payload, images=images)

    def _observation_response(
        self,
        observation: dict[str, Any],
        *,
        reset_executed: bool = False,
    ) -> ToolResponse:
        pixels = observation.get("pixels", {})
        payload: dict[str, Any] = {
            "state": json_safe(observation.get("state", [])),
            "full_state": json_safe(observation.get("full_state", [])),
            "pixel_summary": {},
        }
        if "extrinsics" in observation:
            payload["extrinsics"] = json_safe(observation["extrinsics"])
        if reset_executed:
            payload["reset_executed"] = True

        images: list[ImageArtifact] = []
        for pixel_name, pixel_value in pixels.items():
            pixel_array = np.asarray(pixel_value)
            if pixel_name.endswith("_depth"):
                payload["pixel_summary"][pixel_name] = depth_summary(pixel_array)
                images.append(
                    ImageArtifact(
                        camera=pixel_name,
                        data=depth_preview_png(pixel_array),
                        mime_type="image/png",
                    )
                )
                continue

            payload["pixel_summary"][pixel_name] = {
                "shape": list(pixel_array.shape),
                "dtype": str(pixel_array.dtype),
            }
            images.append(
                ImageArtifact(
                    camera=pixel_name,
                    data=encode_png(pixel_array),
                    mime_type="image/png",
                )
            )

        return ToolResponse(payload=payload, images=images)

