    def navigation_runtime_error(
        self,
        checks: dict[str, dict[str, Any]],
        require_localization: bool,
        require_navigation_plan: bool,
    ) -> Optional[str]:
        missing_services = []
        if require_localization and not checks["localization_server"]["running"]:
            missing_services.append(checks["localization_server"])
        if require_navigation_plan and not checks["service_navigation_plan"]["running"]:
            missing_services.append(checks["service_navigation_plan"])

        if not missing_services:
            return None

        missing_summary = ", ".join(
            f"{service['description']} ({service['path']})"
            for service in missing_services
        )
        return (
            "Required robot services are not running: "
            f"{missing_summary}. "
            "Start the missing service(s) before using navigation or pose APIs. "
            "If localization is missing, you can start it with "
            "`/data/galbot/bin/localization_server`."
        )

    def is_process_running(self, executable_path: str) -> bool:
        executable_name = os.path.basename(executable_path)
        try:
            proc_entries = os.listdir("/proc")
        except OSError:
            return False

        for entry in proc_entries:
            if not entry.isdigit():
                continue
            cmdline_path = os.path.join("/proc", entry, "cmdline")
            try:
                with open(cmdline_path, "rb") as handle:
                    raw_cmdline = handle.read()
            except OSError:
                continue
            if not raw_cmdline:
                continue
            cmdline_parts = [
                part.decode("utf-8", errors="ignore")
                for part in raw_cmdline.split(b"\0")
                if part
            ]
            if executable_path in cmdline_parts:
                return True
            if executable_name in {os.path.basename(part) for part in cmdline_parts}:
                return True
        return False

