def encode_task_inference_png_bytes(image: np.ndarray) -> bytes:
    if cv2 is None:
        raise ImportError("OpenCV (cv2) is required for task inference encoding")
    image_array = np.asarray(image)
    if image_array.ndim != 3 or image_array.shape[2] != 3:
        raise ValueError(
            "task inference image must be an HxWx3 array, "
            f"got shape {image_array.shape}"
        )
    if image_array.dtype != np.uint8:
        image_array = np.clip(image_array, 0, 255).astype(np.uint8)
    success, encoded = cv2.imencode(".png", np.ascontiguousarray(image_array))
    if not success:
        raise RuntimeError("Failed to encode task inference image as PNG")
    return encoded.tobytes()


